const std = @import("std");

const StackAllocator = struct {
    buffer: []u8,
    offset: usize = 0,

    fn alloc(self: *StackAllocator, size: usize) ?[]u8 {
        if (self.offset + size > self.buffer.len) return null;
        const result = self.buffer[self.offset..self.offset + size];
        self.offset += size;
        return result;
    }

    fn reset(self: *StackAllocator) void {
        self.offset = 0;
    }
};

pub fn main() !void {
    var buf: [1024]u8 = undefined;
    var alloc = StackAllocator{ .buffer = &buf };

    const a = (alloc.alloc(4) orelse return);
    const b = (alloc.alloc(8) orelse return);

    std.debug.print("Allocated block sizes: {} and {}\n", .{a.len, b.len});
    std.debug.print("Total used: {}/1024 bytes\n", .{alloc.offset});
}

